class Solution:
    def nextGreaterPermutation(self, nums: list[int]) -> list[int]:
        # Next permutation of nums
        a = list(nums)
        n = len(a)
        i = n - 2
        while i >= 0 and a[i] >= a[i + 1]:
            i -= 1
        if i >= 0:
            j = n - 1
            while a[j] <= a[i]:
                j -= 1
            a[i], a[j] = a[j], a[i]
        # Reverse suffix
        a[i + 1:] = reversed(a[i + 1:])
        return a

#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> nextGreaterPermutation(vector<int>& nums) {
        vector<int> a = nums;
        int n = a.size();
        int i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) {
            i--;
        }
        if (i >= 0) {
            int j = n - 1;
            while (a[j] <= a[i]) {
                j--;
            }
            swap(a[i], a[j]);
        }
        reverse(a.begin() + i + 1, a.end());
        return a;
    }
};

import java.util.*;

class Solution {
    public int[] nextGreaterPermutation(int[] nums) {
        int[] a = nums.clone();
        int n = a.length;
        int i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) {
            i--;
        }
        if (i >= 0) {
            int j = n - 1;
            while (a[j] <= a[i]) {
                j--;
            }
            int t = a[i]; a[i] = a[j]; a[j] = t;
        }
        int l = i + 1, r = n - 1;
        while (l < r) {
            int t = a[l]; a[l] = a[r]; a[r] = t;
            l++; r--;
        }
        return a;
    }
}

var nextGreaterPermutation = function(nums) {
    const a = [...nums];
    const n = a.length;
    let i = n - 2;
    while (i >= 0 && a[i] >= a[i + 1]) {
        i--;
    }
    if (i >= 0) {
        let j = n - 1;
        while (a[j] <= a[i]) {
            j--;
        }
        [a[i], a[j]] = [a[j], a[i]];
    }
    let l = i + 1, r = n - 1;
    while (l < r) {
        [a[l], a[r]] = [a[r], a[l]];
        l++; r--;
    }
    return a;
};
